const REDUCTION_PCT_STORAGE_KEY = 'sustainow_emissions_reduction_target_pct_v1';

const toSafeNumber = (value: unknown): number => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

const formatMonthLabel = (bucket: string) => {
  const [y, m] = bucket.split('-');
  if (!y || !m) return bucket;
  const parsed = new Date(Number(y), Number(m) - 1, 1);
  if (Number.isNaN(parsed.getTime())) return bucket;
  return new Intl.DateTimeFormat('en-IN', { month: 'short', year: 'numeric' }).format(parsed);
};

const parseApiPeriodRows = (raw: unknown): { key: string; kg: number }[] => {
  const maxYear = new Date().getUTCFullYear() + 1;
  const nowKey = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, '0')}`;
  const keepKey = (key: string) => {
    if (!/^(\d{4})-(\d{2})$/.test(key)) return false;
    const year = Number(key.slice(0, 4));
    if (year < 1990 || year > maxYear) return false;
    // Drop future month buckets (DEEP-BUG-028).
    return key <= nowKey;
  };
  if (!raw) return [];
  if (Array.isArray(raw)) {
    return raw
      .filter(Boolean)
      .map((row: Record<string, unknown>) => {
        const key = String(row.periodStart ?? row.period ?? row.startDate ?? row.bucket ?? '');
        const kg = toSafeNumber(row.totalEmissions ?? row.totalCO2Emissions);
        return { key, kg };
      })
      .filter((r) => keepKey(r.key));
  }
  const summary = raw as Record<string, unknown>;
  const groups = summary.groups;
  if (Array.isArray(groups)) {
    return groups
      .map((g: Record<string, unknown>) => ({
        key: String(g.periodStart ?? g.startDate ?? g.bucket ?? g.period ?? ''),
        kg: toSafeNumber(g.totalEmissions ?? g.totalCO2Emissions),
      }))
      .filter((r) => keepKey(r.key));
  }
  const nested =
    (summary as { periodWise?: { monthly?: Record<string, unknown>[] } }).periodWise?.monthly ||
    (summary as { mobileBreakdown?: { periodWise?: { monthly?: Record<string, unknown>[] } } }).mobileBreakdown
      ?.periodWise?.monthly;
  if (Array.isArray(nested)) {
    return nested
      .map((g: Record<string, unknown>) => ({
        key: String(g.period ?? ''),
        kg: toSafeNumber(g.totalCO2Emissions ?? g.totalEmissions),
      }))
      .filter((r) => keepKey(r.key));
  }
  return [];
};

type AiCapability = { id: string; title: string; status?: string; summary?: string; capability?: string };

interface AiAnalyticsPayload {
  degraded?: boolean;
  warning?: string;
  engine?: { name?: string; version?: string; readinessScore?: number; activeAgents?: number; totalAgents?: number };
  capabilities?: AiCapability[];
  synthesis?: Record<string, unknown>;
  benchmarks?: {
    industryAverageKg?: number;
    bestInClassKg?: number;
    previousAssessmentKg?: number;
  };
  charts?: {
    scopeMonthlyStack?: Array<{
      period: string;
      label: string;
      scope1: number;
      scope2: number;
      scope3: number;
      total: number;
    }>;
  };
  compliance?: { summary?: string; readinessPercent?: number };
}

const quarterKey = (bucket: string) => {
  const [y, m] = bucket.split('-').map(Number);
  if (!y || !m) return bucket;
  const q = Math.floor((m - 1) / 3) + 1;
  return `${y}-Q${q}`;
};

const halfYearKey = (bucket: string) => {
  const [y, m] = bucket.split('-').map(Number);
  if (!y || !m) return bucket;
  return `${y}-H${m <= 6 ? 1 : 2}`;
};

const yearKey = (bucket: string) => bucket.slice(0, 4);

const formatKgCo2e = (value: number, digits = 1) =>
  formatCo2eFromKg(value, { unit: 'kg', maximumFractionDigits: digits });

const stickyLeadCellSx = {
  position: 'sticky',
  left: 0,
  zIndex: 2,
  bgcolor: 'background.paper',
  whiteSpace: 'nowrap',
} as const;

const PeriodStatusChip: React.FC<{ status: string }> = ({ status }) => (
  <Chip
    size="small"
    label={status}
    color={status === 'Within target' ? 'success' : 'warning'}
    variant="outlined"
  />
);

const EmissionsReductionTargets: React.FC = () => {
  const navigate = useNavigate();
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const gridStroke = cartesianGridStroke(isDark);
  const tickStyle = axisTickForMode(isDark);
  const tipProps = rechartsTooltipProps(isDark);
  const prefersReducedMotion = usePrefersReducedMotion();
  const chartMotion = chartAnimationPropsFor(prefersReducedMotion);
  const isNarrow = useMediaQuery(theme.breakpoints.down('sm'));

  const [searchParams] = useSearchParams();
  const [innerTab, setInnerTab] = useUrlTabParam(0, { maxTab: 1 });
  const [loading, setLoading] = useState(true);
  const [seriesRefreshing, setSeriesRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [targetSaveState, setTargetSaveState] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const [monthlySeries, setMonthlySeries] = useState<{ key: string; kg: number }[]>([]);
  const [reductionPct, setReductionPct] = useState(10);
  const [maintenanceUnitPriceInr, setMaintenanceUnitPriceInr] = useState(200);
  const [aiPayload, setAiPayload] = useState<AiAnalyticsPayload | null>(null);

  // Reduction ideas live under Emissions → Reduction ideas (not duplicated here).
  useEffect(() => {
    const rawTab = searchParams.get('tab');
    if (rawTab === '2') {
      navigate('/carbon-footprint?section=recommendations', { replace: true });
    }
  }, [searchParams, navigate]);

  const reductionEditGen = useRef(0);

  const persistReduction = useCallback(async (value: number) => {
    const clamped = Math.min(40, Math.max(0, value));
    reductionEditGen.current += 1;
    setReductionPct(clamped);
    localStorage.setItem(REDUCTION_PCT_STORAGE_KEY, String(clamped));
    setTargetSaveState('saving');
    try {
      await ApiService.updateReductionTarget(clamped);
      setTargetSaveState('saved');
    } catch (e) {
      console.error('Failed to sync reduction target:', e);
      setTargetSaveState('error');
    }
  }, []);

  const persistMaintenanceUnitPrice = useCallback(async (value: number) => {
    const clamped = Math.min(1000, Math.max(50, Math.round(value)));
    setMaintenanceUnitPriceInr(clamped);
    try {
      await ApiService.updateMaintenanceUnitPrice(clamped);
    } catch (e) {
      console.error('Failed to sync maintenance unit price:', e);
    }
  }, []);

  useEffect(() => {
    let active = true;
    const loadTarget = async () => {
      const generationAtStart = reductionEditGen.current;
      const stored = Number(localStorage.getItem(REDUCTION_PCT_STORAGE_KEY));
      if (Number.isFinite(stored) && stored >= 0 && stored <= 40) {
        setReductionPct(stored);
      }
      try {
        const [targetResponse, maintenanceResponse] = await Promise.all([
          ApiService.getReductionTarget(),
          ApiService.getMaintenanceUnitPrice().catch(() => null),
        ]);
        const pct = Number(
          (targetResponse as { data?: { reductionTargetPct?: number } })?.data?.reductionTargetPct
        );
        if (
          active
          && reductionEditGen.current === generationAtStart
          && Number.isFinite(pct)
          && pct >= 0
          && pct <= 40
        ) {
          setReductionPct(pct);
          localStorage.setItem(REDUCTION_PCT_STORAGE_KEY, String(pct));
        }
        const maintenancePrice = Number(
          (maintenanceResponse as { data?: { maintenanceUnitPriceInr?: number } })?.data?.maintenanceUnitPriceInr
        );
        if (active && Number.isFinite(maintenancePrice) && maintenancePrice >= 50 && maintenancePrice <= 1000) {
          setMaintenanceUnitPriceInr(maintenancePrice);
        }
      } catch {
        // Keep local fallback when profile is unavailable.
      }
    };
    void loadTarget();
    return () => {
      active = false;
    };
  }, []);

  const refreshAi = useCallback(async () => {
    try {
      // Server reads a capped ledger sample. Do not post the full voucher list.
      const response = await ApiService.runCarbonAIAnalyticsEngine({});
      const envelope = response as { data?: AiAnalyticsPayload; degraded?: boolean; warning?: string };
      const payload = envelope?.data ?? (response as AiAnalyticsPayload);
      if (payload && typeof payload === 'object' && !envelope?.degraded && !(payload as AiAnalyticsPayload).degraded) {
        setAiPayload(payload as AiAnalyticsPayload);
      } else {
        setAiPayload(null);
      }
    } catch (e) {
      console.error('Carbon analytics for targets:', e);
      setAiPayload(null);
    }
  }, []);

  const seriesLoadedRef = useRef(false);
  const aiLoadedRef = useRef(false);

  const loadSeries = useCallback(async (force = false) => {
    if (seriesLoadedRef.current && !force) {
      return;
    }
    const showFullLoader = !seriesLoadedRef.current;
    if (showFullLoader) {
      setLoading(true);
    } else {
      setSeriesRefreshing(true);
    }
    setError(null);
    try {
      // DEEP-BUG-035: do not first-paint a stale period API baseline (e.g. Jul-2022-only).
      // Always merge live transactions before publishing Progress charts.
      const ledgerMonthly = typeof ApiService.getLedgerMonthlyEmissions === 'function'
        ? await ApiService.getLedgerMonthlyEmissions({ limit: 36, fresh: force }).catch(() => null)
        : null;
      const liveRows = parseApiPeriodRows(
        (ledgerMonthly as { data?: { summary?: unknown } } | null)?.data?.summary
        ?? (ledgerMonthly as { summary?: unknown } | null)?.summary
      );
      const periodResponse = liveRows.length > 0
        ? null
        : await ApiService.getCarbonAssessmentByPeriod({
          groupBy: 'monthly',
          limit: 36,
        }).catch(() => null);
      const rawSummary =
        (periodResponse as { data?: { summary?: unknown } } | null)?.data?.summary ??
        (periodResponse as { summary?: unknown } | null)?.summary ??
        (periodResponse as { data?: unknown } | null)?.data;
      const apiRows = liveRows.length > 0 ? liveRows : parseApiPeriodRows(rawSummary);
      setMonthlySeries(apiRows);
      seriesLoadedRef.current = true;
    } catch (e) {
      console.error(e);
      setError('Unable to load emissions history for targets.');
      setMonthlySeries([]);
    } finally {
      setLoading(false);
      setSeriesRefreshing(false);
    }
  }, []);

  const loadAiForProgress = useCallback(async () => {
    if (aiLoadedRef.current) {
      return;
    }
    aiLoadedRef.current = true;
    try {
      await refreshAi();
    } catch (e) {
      console.error(e);
      aiLoadedRef.current = false;
    }
  }, [refreshAi]);

  useEffect(() => {
    void loadSeries();
  }, [loadSeries]);

  // AI + full transaction crawl only when Progress & charts is open.
  useEffect(() => {
    if (innerTab === 0) {
      void loadAiForProgress();
    }
  }, [innerTab, loadAiForProgress]);

  const targetModel = useMemo(() => {
    const series = monthlySeries.filter((m) => m.kg > 0);
    if (series.length === 0) {
      return {
        baselineMonthly: 0,
        annualTargetKg: 0,
        monthlyFlatTarget: 0,
        glideTargets: monthlySeries.map(() => 0),
      };
    }
    const tail = series.slice(-Math.min(3, series.length));
    const baselineMonthly = tail.reduce((s, x) => s + x.kg, 0) / tail.length;
    const annualTargetKg = baselineMonthly * 12 * (1 - reductionPct / 100);
    const monthlyFlatTarget = annualTargetKg / 12;
    const glideTargets = monthlySeries.map((_, idx) => {
      const t = monthlySeries.length > 1 ? idx / (monthlySeries.length - 1) : 0;
      return baselineMonthly * (1 - (reductionPct / 100) * t);
    });
    return { baselineMonthly, annualTargetKg, monthlyFlatTarget, glideTargets };
  }, [monthlySeries, reductionPct]);

  const chartRows = useMemo(() => {
    const slice = monthlySeries.slice(-24);
    return slice.map((row) => {
      const globalIdx = monthlySeries.findIndex((m) => m.key === row.key);
      const glide =
        globalIdx >= 0 && targetModel.glideTargets[globalIdx] != null
          ? targetModel.glideTargets[globalIdx]
          : targetModel.monthlyFlatTarget;
      const flat = targetModel.monthlyFlatTarget;
      return {
        key: row.key,
        label: formatMonthLabel(row.key),
        actualKg: Number(row.kg.toFixed(2)),
        targetKg: Number((flat > 0 ? flat : glide).toFixed(2)),
        glideTargetKg: Number(glide.toFixed(2)),
        variance: Number((row.kg - (flat > 0 ? flat : glide)).toFixed(2)),
      };
    });
  }, [monthlySeries, targetModel]);

  const quarterlyRows = useMemo(() => {
    const map = new Map<string, { actual: number; months: number }>();
    monthlySeries.forEach((m) => {
      const qk = quarterKey(m.key);
      const cur = map.get(qk) || { actual: 0, months: 0 };
      cur.actual += m.kg;
      cur.months += 1;
      map.set(qk, cur);
    });
    const quarterlyTarget = targetModel.annualTargetKg / 4;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, v]) => ({
        period,
        actual: v.actual,
        target: quarterlyTarget,
        progressPct: quarterlyTarget > 0 ? (v.actual / quarterlyTarget) * 100 : 0,
        status: quarterlyTarget > 0 && v.actual <= quarterlyTarget ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const halfYearRows = useMemo(() => {
    const map = new Map<string, number>();
    monthlySeries.forEach((m) => {
      const hk = halfYearKey(m.key);
      map.set(hk, (map.get(hk) || 0) + m.kg);
    });
    const halfTarget = targetModel.annualTargetKg / 2;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([period, actual]) => ({
        period,
        actual,
        target: halfTarget,
        progressPct: halfTarget > 0 ? (actual / halfTarget) * 100 : 0,
        status: halfTarget > 0 && actual <= halfTarget ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const annualRows = useMemo(() => {
    const map = new Map<string, number>();
    monthlySeries.forEach((m) => {
      const yk = yearKey(m.key);
      map.set(yk, (map.get(yk) || 0) + m.kg);
    });
    const annualT = targetModel.annualTargetKg;
    return Array.from(map.entries())
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([year, actual]) => ({
        year,
        actual,
        target: annualT,
        progressPct: annualT > 0 ? (actual / annualT) * 100 : 0,
        status: annualT > 0 && actual <= annualT ? 'Within target' : 'Above target',
      }));
  }, [monthlySeries, targetModel.annualTargetKg]);

  const ytdSummary = useMemo(() => {
    const now = new Date();
    const y = now.getFullYear();
    const ytd = monthlySeries.filter((m) => m.key.startsWith(String(y))).reduce((s, m) => s + m.kg, 0);
    const monthsElapsed = Math.max(1, monthlySeries.filter((m) => m.key.startsWith(String(y))).length || now.getMonth() + 1);
    const ytdTarget = (targetModel.annualTargetKg / 12) * monthsElapsed;
    const score = ytdTarget > 0 ? Math.round(Math.min(100, (ytdTarget / Math.max(ytd, 0.001)) * 100)) : 0;
    return { ytd, ytdTarget, score, year: y, monthsElapsed };
  }, [monthlySeries, targetModel.annualTargetKg]);

  const scopeStackRows = useMemo(() => aiPayload?.charts?.scopeMonthlyStack ?? aiPayload?.charts?.scopeMonthlyStack ?? [], [aiPayload]);

  const chartYMax = useMemo(() => {
    let m = 1;
    chartRows.forEach((r) => {
      m = Math.max(m, r.actualKg, r.targetKg, r.glideTargetKg);
    });
    return m;
  }, [chartRows]);

  const industryAvgMonthly = useMemo(() => {
    const v = toSafeNumber(aiPayload?.benchmarks?.industryAverageKg);
    return v > 0 ? v / 12 : 0;
  }, [aiPayload]);

  const bestInClassMonthly = useMemo(() => {
    const v = toSafeNumber(aiPayload?.benchmarks?.bestInClassKg);
    return v > 0 ? v / 12 : 0;
  }, [aiPayload]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight={360} gap={2}>
        <CircularProgress />
        <Typography variant="body1">Loading emissions and targets…</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <WorkspacePageHeader
        title="Emissions reduction targets"
        description={`Compare recorded kg CO₂e against glide and flat budgets. The percentage is a run-rate cut from the trailing three active months, shown against every period in the tables. ${CO2E_METHODOLOGY_SUBTITLE}`}
        actions={(
          <Tooltip title="Reload the emissions series">
            <span>
              <IconButton
                aria-label="Reload emissions series"
                aria-busy={seriesRefreshing}
                disabled={seriesRefreshing}
                onClick={() => { void loadSeries(true); }}
              >
                {seriesRefreshing ? <CircularProgress size={18} /> : <RefreshIcon />}
              </IconButton>
            </span>
          </Tooltip>
        )}
      />

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}


      <Card variant="outlined" sx={{ mb: 2 }}>
        <CardContent>
          <Typography variant="subtitle1" gutterBottom>
            Annual reduction ambition
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            Baseline is the average of the last three months with emissions above zero. This slider models a
            {` ${reductionPct}% `}
            cut from that monthly run-rate. It is not a comparison with the previous calendar year. Release the slider to save.
          </Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
            <Slider
              value={reductionPct}
              onChange={(_, v) => {
                const next = Array.isArray(v) ? v[0] : v;
                setReductionPct(Math.min(40, Math.max(0, next)));
              }}
              onChangeCommitted={(_, v) => {
                const next = Array.isArray(v) ? v[0] : v;
                void persistReduction(next);
              }}
              min={0}
              max={40}
              step={1}
              valueLabelDisplay="auto"
              aria-label="Annual emissions reduction percent"
              sx={{ maxWidth: { sm: 420 }, flex: 1, py: 1 }}
            />
            <Chip label={`${reductionPct}% run-rate cut`} color="primary" variant="outlined" />
          </Stack>
          {targetSaveState === 'saving' && (
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
              Saving percentage…
            </Typography>
          )}
          {targetSaveState === 'saved' && (
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
              Percentage saved to your company profile.
            </Typography>
          )}
          {targetSaveState === 'error' && (
            <Alert severity="warning" sx={{ mt: 1 }}>
              The percentage is still shown here, and it could not be saved to the server. Try releasing the slider again.
            </Alert>
          )}
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Baseline (avg last 3 active months)
              </Typography>
              <Typography variant="h6">{formatKgCo2e(targetModel.baselineMonthly, 1)} / month</Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Modelled annual target
              </Typography>
              <Typography variant="h6">{formatKgCo2e(targetModel.annualTargetKg, 0)}</Typography>
              <Typography variant="caption" color="text.secondary">
                Baseline × 12 × (1 − cut). The same figure is used for every year in the tables.
              </Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <Typography variant="caption" color="text.secondary">
                Flat monthly budget (target ÷ 12)
              </Typography>
              <Typography variant="h6">{formatKgCo2e(targetModel.monthlyFlatTarget, 1)} / month</Typography>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      <Card variant="outlined" sx={{ mb: 2 }}>
        <CardContent>
          <Typography variant="subtitle1" gutterBottom>
            Maintenance spend proxy
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
            AMC and repair vouchers without a counted service unit use ₹ per service unit to screen maintenance emissions
            (0.1 kg CO₂e per unit). That screening row stays in the 1% estimate check. A Quantity with unit service_unit, visit, or job is activity-based and leaves the check. Changing this rate does not. Saved settings
            also appear under{' '}
            <Link component={RouterLink} to="/msme-profile#carbon-methodology">
              My company → Carbon methodology settings
            </Link>
            .
          </Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
            <Slider
              value={maintenanceUnitPriceInr}
              onChange={(_, v) => {
                const next = Array.isArray(v) ? v[0] : v;
                setMaintenanceUnitPriceInr(Math.min(1000, Math.max(50, Math.round(next))));
              }}
              onChangeCommitted={(_, v) => {
                const next = Array.isArray(v) ? v[0] : v;
                void persistMaintenanceUnitPrice(next);
              }}
              min={50}
              max={1000}
              step={10}
              valueLabelDisplay="auto"
              aria-label="Maintenance service unit price in INR"
              sx={{ maxWidth: { sm: 360 }, flex: 1 }}
            />
            <Chip label={`₹${maintenanceUnitPriceInr} / service unit`} color="default" variant="outlined" />
          </Stack>
        </CardContent>
      </Card>

      <Tabs
        value={innerTab}
        onChange={(_event, value) => setInnerTab(value)}
        sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}
      >
        <Tab label="Progress & charts" id="ert-tab-0" aria-controls="ert-panel-0" />
        <Tab label="Targets" id="ert-tab-1" aria-controls="ert-panel-1" />
      </Tabs>

      {innerTab === 0 && (
        <Stack spacing={2}>
          {aiPayload?.capabilities && aiPayload.capabilities.length > 0 && (
            <Card variant="outlined">
              <CardContent>
                <Stack direction="row" alignItems="center" spacing={1} sx={{ mb: 1 }}>
                  <AutoAwesomeIcon color="primary" fontSize="small" />
                  <Typography variant="subtitle1">Carbon analytics status</Typography>
                  {typeof aiPayload.engine?.readinessScore === 'number' && (
                    <Chip size="small" label={`Engine readiness ${aiPayload.engine.readinessScore}%`} variant="outlined" />
                  )}
                </Stack>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                  Carbon analytics modules power scope stacks and recommendations when active in your workspace.
                </Typography>
                <Stack direction="row" flexWrap="wrap" gap={0.75}>
                  {aiPayload.capabilities.map((cap) => (
                    <Chip
                      key={cap.id}
                      size="small"
                      color={cap.status === 'active' ? 'success' : 'default'}
                      variant={cap.status === 'active' ? 'filled' : 'outlined'}
                      label={cap.title}
                    />
                  ))}
                </Stack>
              </CardContent>
            </Card>
          )}

          <Card variant="outlined">
            <CardContent>
              <Typography variant="h6" gutterBottom>
                {ytdSummary.year} progress vs prorated target
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                {ytdSummary.year} actual emissions for months that appear in the loaded series, compared with the annual target
                prorated by that month count ({ytdSummary.monthsElapsed}). A score of 100 means actual is at or under that budget.
                Months with no row are left out of both sides. This is not a calendar-month proration.
              </Typography>
              <Stack spacing={1} sx={{ maxWidth: 520 }}>
                <Stack direction="row" justifyContent="space-between" spacing={2}>
                  <Typography variant="body2">YTD actual</Typography>
                  <Typography variant="body2" fontWeight={600}>
                    {formatKgCo2e(ytdSummary.ytd, 1)}
                  </Typography>
                </Stack>
                <Stack direction="row" justifyContent="space-between" spacing={2}>
                  <Typography variant="body2">YTD target (months with rows)</Typography>
                  <Typography variant="body2" fontWeight={600}>
                    {formatKgCo2e(ytdSummary.ytdTarget, 1)}
                  </Typography>
                </Stack>
                <Typography variant="caption" color="text.secondary">
                  On-track score (100 = at or under the prorated budget for those months)
                </Typography>
                <LinearProgress
                  variant="determinate"
                  value={Math.min(100, ytdSummary.score)}
                  aria-label={`On-track score ${ytdSummary.score} percent`}
                  sx={{ height: 10, borderRadius: 1 }}
                  color={ytdSummary.score >= 95 ? 'success' : ytdSummary.score >= 80 ? 'warning' : 'error'}
                />
                <Typography variant="caption">{ytdSummary.score}%</Typography>
              </Stack>
            </CardContent>
          </Card>

          <Card variant="outlined">
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Actual vs target emissions over time
              </Typography>
              <Typography variant="body2" color="text.secondary" paragraph>
                Bars are recorded monthly kg CO₂e. The red line is the flat monthly budget. The dashed blue line is a glide
                across the loaded months by position: baseline at the first month, reduced rate at the last month. It is not a
                forward calendar year. Orange and purple lines appear only when the latest assessment stores industry and
                best-in-class numbers. Those stored numbers are divided by 12 on this chart. They are context lines, not the monthly budget.
              </Typography>
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                {CO2E_METHODOLOGY_SUBTITLE}
                {' '}
                Tooltips stay in kg CO₂e. Axis ticks switch to tonnes when the largest value is at least 1,000 kg.
              </Typography>
              {chartRows.length === 0 ? (
                <Alert severity="info">
                  No emissions for the selected history. Add dated transactions with carbon footprints or complete a periodic
                  assessment so this chart is not mistaken for zero emissions.
                </Alert>
              ) : (
                <Box
                  sx={{ width: '100%', minWidth: 0, height: { xs: 320, sm: 400 }, overflow: 'hidden' }}
                  role="img"
                  aria-label="Monthly actual emissions as bars with flat and glide target lines and optional benchmark references."
                >
                  <ResponsiveContainer width="100%" height="100%">
                    <ComposedChart data={chartRows} margin={{ top: 12, right: 16, left: 4, bottom: isNarrow ? 20 : 8 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                      <XAxis
                        dataKey="label"
                        tick={{ ...tickStyle, fontSize: isNarrow ? 10 : 11 }}
                        interval="preserveStartEnd"
                        angle={isNarrow ? -35 : 0}
                        textAnchor={isNarrow ? 'end' : 'middle'}
                        height={isNarrow ? 64 : 32}
                        minTickGap={8}
                      />
                      <YAxis
                        width={isNarrow ? 44 : 72}
                        tick={{ ...tickStyle, fontSize: isNarrow ? 10 : 11 }}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={isNarrow ? undefined : {
                          value: yAxisLabelForKgDomain(chartYMax),
                          angle: -90,
                          position: 'insideLeft',
                          fill: tickStyle.fill,
                          fontSize: 11,
                          offset: 8,
                        }}
                      />
                      <RechartsTooltip
                        {...tipProps}
                        formatter={(v: number, name: string) => [formatKgCo2e(toSafeNumber(v), 1), name]}
                      />
                      <Legend
                        {...rechartsLegendProps}
                        wrapperStyle={{ ...rechartsLegendProps.wrapperStyle, fontSize: 12, lineHeight: '18px' }}
                      />
                      {industryAvgMonthly > 0 && (
                        <ReferenceLine
                          y={industryAvgMonthly}
                          stroke="#ea580c"
                          strokeDasharray="4 4"
                          label={{ value: 'Industry (prorated)', fill: tickStyle.fill, fontSize: 10 }}
                        />
                      )}
                      {bestInClassMonthly > 0 && (
                        <ReferenceLine
                          y={bestInClassMonthly}
                          stroke="#7c3aed"
                          strokeDasharray="3 6"
                          label={{ value: 'Best in class (prorated)', fill: tickStyle.fill, fontSize: 10 }}
                        />
                      )}
                      <Bar dataKey="actualKg" name="Actual" fill="#059669" radius={[6, 6, 0, 0]} {...chartMotion} />
                      <Line
                        type="monotone"
                        dataKey="targetKg"
                        name="Flat monthly target"
                        stroke="#be123c"
                        strokeWidth={2.5}
                        dot={false}
                        activeDot={{ r: 5 }}
                        {...chartMotion}
                      />
                      <Line
                        type="monotone"
                        dataKey="glideTargetKg"
                        name="Glide target"
                        stroke="#2563eb"
                        strokeDasharray="6 4"
                        strokeWidth={2}
                        dot={false}
                        activeDot={{ r: 5 }}
                        {...chartMotion}
                      />
                    </ComposedChart>
                  </ResponsiveContainer>
                </Box>
              )}
            </CardContent>
          </Card>

          {scopeStackRows.length > 0 && (
            <Card variant="outlined">
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Monthly emissions by scope (transactions)
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Stacked bars use the carbon analytics sample of recent transactions, grouped by month on this device’s local
                  calendar. The bars above sum the ledger by UTC month. The two charts can disagree for the same label. This
                  stack is not a second inventory total.
                </Typography>
                <Box
                  sx={{ width: '100%', minWidth: 0, height: { xs: 300, sm: 340 }, overflow: 'hidden' }}
                  role="img"
                  aria-label="Stacked bar chart of scope one two and three emissions by month from the analytics transaction sample."
                >
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={scopeStackRows} margin={{ top: 12, right: 16, left: 4, bottom: isNarrow ? 20 : 8 }}>
                      <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} vertical={false} />
                      <XAxis
                        dataKey="label"
                        tick={{ ...tickStyle, fontSize: isNarrow ? 10 : 11 }}
                        interval="preserveStartEnd"
                        angle={isNarrow ? -35 : 0}
                        textAnchor={isNarrow ? 'end' : 'middle'}
                        height={isNarrow ? 64 : 32}
                        minTickGap={8}
                      />
                      <YAxis
                        width={isNarrow ? 44 : 72}
                        tick={{ ...tickStyle, fontSize: isNarrow ? 10 : 11 }}
                        tickFormatter={(v: number) => formatAxisTickKg(v)}
                        label={isNarrow ? undefined : {
                          value: yAxisLabelForKgDomain(Math.max(...scopeStackRows.map((r) => r.total), 1)),
                          angle: -90,
                          position: 'insideLeft',
                          fill: tickStyle.fill,
                          fontSize: 11,
                          offset: 8,
                        }}
                      />
                      <RechartsTooltip {...tipProps} formatter={(v: number, name: string) => [formatKgCo2e(toSafeNumber(v), 1), name]} />
                      <Legend
                        {...rechartsLegendProps}
                        wrapperStyle={{ ...rechartsLegendProps.wrapperStyle, fontSize: 12, lineHeight: '18px' }}
                      />
                      <Bar dataKey="scope1" stackId="scopes" name="Scope 1" fill={GHG_SCOPE_HEX.scope1} {...chartMotion} />
                      <Bar dataKey="scope2" stackId="scopes" name="Scope 2" fill={GHG_SCOPE_HEX.scope2} {...chartMotion} />
                      <Bar dataKey="scope3" stackId="scopes" name="Scope 3" fill={GHG_SCOPE_HEX.scope3} {...chartMotion} />
                    </BarChart>
                  </ResponsiveContainer>
                </Box>
              </CardContent>
            </Card>
          )}
        </Stack>
      )}

      {innerTab === 1 && (
        <Stack spacing={3}>
          <Alert severity="info">
            Every target column uses the current modelled budget from the trailing three active months. Closed years are not
            given a separate historical target. Quarter, half-year, and year status compare actual emissions with the full
            period budget, including periods that are still open. On a narrow screen, swipe each table sideways. The first column stays put.
          </Alert>
          <Box>
            <Typography variant="h6" gutterBottom>
              Monthly
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              Positive variance means the month is above the flat monthly budget. Values stay in kg CO₂e.
            </Typography>
            <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
              <Table size="small" stickyHeader sx={{ minWidth: 560 }}>
                <TableHead>
                  <TableRow>
                    <TableCell sx={stickyLeadCellSx}>Month</TableCell>
                    <TableCell align="right">Actual</TableCell>
                    <TableCell align="right">Flat target</TableCell>
                    <TableCell align="right">Variance</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {[...monthlySeries].reverse().map((m) => {
                    const tgt = targetModel.monthlyFlatTarget;
                    const v = m.kg - tgt;
                    return (
                      <TableRow key={m.key}>
                        <TableCell sx={stickyLeadCellSx}>{formatMonthLabel(m.key)}</TableCell>
                        <TableCell align="right">{formatKgCo2e(m.kg, 1)}</TableCell>
                        <TableCell align="right">{formatKgCo2e(tgt, 1)}</TableCell>
                        <TableCell align="right" sx={{ color: v > 0 ? 'warning.main' : 'text.primary' }}>
                          {formatKgCo2e(v, 1)}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                  {monthlySeries.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={4} align="center">
                        No monthly data yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Quarterly
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              Target is the modelled annual figure divided by 4, for every quarter in the series.
            </Typography>
            <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
              <Table size="small" stickyHeader sx={{ minWidth: 640 }}>
                <TableHead>
                  <TableRow>
                    <TableCell sx={stickyLeadCellSx}>Quarter</TableCell>
                    <TableCell align="right">Actual</TableCell>
                    <TableCell align="right">Full-quarter target</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {quarterlyRows.map((r) => (
                    <TableRow key={r.period}>
                      <TableCell sx={stickyLeadCellSx}>{r.period}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.actual, 1)}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.target, 1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell><PeriodStatusChip status={r.status} /></TableCell>
                    </TableRow>
                  ))}
                  {quarterlyRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No quarterly rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Half-year
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              Target is the modelled annual figure divided by 2, for every half-year in the series.
            </Typography>
            <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
              <Table size="small" stickyHeader sx={{ minWidth: 640 }}>
                <TableHead>
                  <TableRow>
                    <TableCell sx={stickyLeadCellSx}>Half-year</TableCell>
                    <TableCell align="right">Actual</TableCell>
                    <TableCell align="right">Full half-year target</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {halfYearRows.map((r) => (
                    <TableRow key={r.period}>
                      <TableCell sx={stickyLeadCellSx}>{r.period}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.actual, 1)}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.target, 1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell><PeriodStatusChip status={r.status} /></TableCell>
                    </TableRow>
                  ))}
                  {halfYearRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No half-year rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>

          <Box>
            <Typography variant="h6" gutterBottom>
              Annual
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
              Target is the current modelled annual budget, repeated for each year that has rows. An open year is still compared with that full-year figure.
            </Typography>
            <TableContainer component={Paper} variant="outlined" sx={{ overflowX: 'auto' }}>
              <Table size="small" stickyHeader sx={{ minWidth: 640 }}>
                <TableHead>
                  <TableRow>
                    <TableCell sx={stickyLeadCellSx}>Year</TableCell>
                    <TableCell align="right">Actual</TableCell>
                    <TableCell align="right">Modelled annual target</TableCell>
                    <TableCell align="right">% of target</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {annualRows.map((r) => (
                    <TableRow key={r.year}>
                      <TableCell sx={stickyLeadCellSx}>{r.year}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.actual, 1)}</TableCell>
                      <TableCell align="right">{formatKgCo2e(r.target, 1)}</TableCell>
                      <TableCell align="right">{r.progressPct.toFixed(0)}%</TableCell>
                      <TableCell><PeriodStatusChip status={r.status} /></TableCell>
                    </TableRow>
                  ))}
                  {annualRows.length === 0 && (
                    <TableRow>
                      <TableCell colSpan={5} align="center">
                        No annual rollups yet.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        </Stack>
      )}

      <Card variant="outlined" sx={{ mt: 2 }}>
        <CardContent>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5} alignItems={{ sm: 'center' }}>
            <AutoAwesomeIcon color="primary" fontSize="small" />
            <Box sx={{ flex: 1 }}>
              <Typography variant="subtitle2">Reduction ideas</Typography>
              <Typography variant="body2" color="text.secondary">
                Actionable recommendations live under Emissions → Reduction ideas (not duplicated here).
              </Typography>
            </Box>
            <Button
              variant="outlined"
              size="small"
              onClick={() => navigate('/carbon-footprint?section=recommendations')}
            >
              Open reduction ideas
            </Button>
          </Stack>
        </CardContent>
      </Card>
    </Box>
  );
};

export default EmissionsReductionTargets;
